import test from 'node:test';
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { createBouquet } from '../src/botany.js';

// These full-buffer digests were captured from the independent, unmodified
// sampler, not generated by the cached implementation under test.
const reference = JSON.parse(readFileSync(new URL('./fixtures/botany-sampling-v8.json', import.meta.url)));
const digest = array => createHash('sha256').update(Buffer.from(array.buffer, array.byteOffset, array.byteLength)).digest('hex');

test('cached sampling preserves the original Float32 values for every form, series and variant', () => {
  const flower = createBouquet({ seed: reference.seed, scale: reference.scale });
  try {
    for (const [key, expected] of Object.entries(reference.samples)) {
      const [form, series, variant] = key.split('/');
      flower.setForm(form); flower.setMaterial(series, variant);
      assert.equal(flower.form, form); assert.equal(flower.series, series); assert.equal(flower.variant, variant);
      const samples = flower.sampleSurface(reference.count);
      for (const attribute of ['closed', 'open', 'colors']) assert.equal(digest(samples[attribute]), expected[attribute], `${key}/${attribute}`);
      assert.equal(digest(flower.sampleColors(reference.count)), expected.colors, `${key}/colors-only`);
    }
  } finally { flower.dispose(); }
});

test('callers cannot mutate the private endpoints or subsequent colors', () => {
  const flower = createBouquet();
  try {
    const first = flower.sampleSurface(257), expected = Object.fromEntries(Object.entries(first).map(([key, value]) => [key, value.slice()]));
    for (const array of Object.values(first)) array.fill(NaN);
    const colors = flower.sampleColors(257);
    assert.deepEqual(colors, expected.colors); colors.fill(-100);
    const next = flower.sampleSurface(257);
    for (const key of ['closed', 'open', 'colors']) {
      assert.notEqual(next[key], first[key]); assert.deepEqual(next[key], expected[key]);
    }
    // A new count replaces the retained sample. Returning to the old count
    // must rebuild the same deterministic IDs, including after the empty case.
    for (const count of [11, 0, 31]) assert.equal(flower.sampleColors(count).length, count * 3);
    assert.deepEqual(flower.sampleSurface(257), expected);
    flower.setForm('lotus');
    assert.notDeepEqual(flower.sampleSurface(257).open, expected.open);
    flower.setForm('lily');
    assert.deepEqual(flower.sampleSurface(257), expected);
  } finally { flower.dispose(); }
});

test('colors-only sampling validates counts, handles empty input and rejects disposed bouquets', () => {
  const flower = createBouquet();
  try {
    const empty = flower.sampleColors(0);
    assert.ok(empty instanceof Float32Array); assert.equal(empty.length, 0);
    assert.notEqual(flower.sampleColors(0), empty);
    for (const count of [-1, 1.5, NaN, Infinity, '4', undefined]) {
      assert.throws(() => flower.sampleColors(count), RangeError);
      assert.throws(() => flower.sampleSurface(count), RangeError);
    }
    flower.setMaterial('not-a-series', 'not-a-variant');
    assert.equal(flower.series, 'silver'); assert.equal(flower.variant, 'blush');
    flower.sampleSurface(17); flower.dispose(); flower.dispose();
    for (const count of [0, 17]) {
      assert.throws(() => flower.sampleSurface(count), /disposed/);
      assert.throws(() => flower.sampleColors(count), /disposed/);
    }
  } finally { flower.dispose(); }
});
